function stableHash(s){let h=2166136261>>>0;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)>>>0}return h>>>0}
function ademicRuneSvg(payload){
 const src=JSON.stringify(payload),h=stableHash(src),cx=90,top=18,bottom=162;
 const points=[[cx,top],[cx,bottom],[34,48],[146,48],[34,90],[146,90],[34,132],[146,132],[58,28],[122,28],[58,152],[122,152]];
 const lines=[[0,1]];
 for(let i=0;i<7;i++){const a=(h>>(i*4))%points.length,b=(h>>(i*4+2))%points.length;if(a!==b)lines.push([a,b])}
 const circle=(payload.resonance?.tone==='reverent'||payload.resonance?.mode==='prayer')?`<circle cx="90" cy="90" r="70" fill="none" stroke="currentColor" stroke-width="3" opacity=".45"/>`:'';
 const dash=payload.resonance?.certainty==='uncertain'?`stroke-dasharray="7 6"`:'';
 return `<svg viewBox="0 0 180 180" role="img" aria-label="Generated Ademic rune"><g fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round" stroke-linejoin="round" ${dash}>${circle}${lines.map(([a,b])=>`<line x1="${points[a][0]}" y1="${points[a][1]}" x2="${points[b][0]}" y2="${points[b][1]}"/>`).join('')}</g></svg>`
}
function cantusPayload(){
 return {phrase:$('#cantusPhrase').value.trim(),meaning:{subject:$('#cSubject').value.trim(),action:$('#cAction').value.trim(),relation:$('#cRelation').value.trim(),context:$('#cContext').value.trim(),conditions:$('#cConditions').value.trim(),consent:$('#cConsent').value.trim()},resonance:{tone:$('#cTone').value,force:$('#cForce').value,mode:$('#cMode').value,intent:$('#cIntent').value,posture:$('#cPosture').value,register:$('#cRegister').value,certainty:$('#cCertainty').value},system:'ADEMIC_CANTUS_V1',rune:'ADEMIC_CONSTRUCTED_NOT_HISTORICAL'}
}
function cantusExpansion(p){const m=p.meaning,r=p.resonance;return `Plain phrase: ${p.phrase}\n\nMeaning\n• subject: ${m.subject||'unspecified'}\n• action: ${m.action||'unspecified'}\n• relation/object: ${m.relation||'unspecified'}\n• context: ${m.context||'unspecified'}\n• conditions: ${m.conditions||'unspecified'}\n• consent/boundary: ${m.consent||'unspecified'}\n\nResonance\n• tone: ${r.tone}\n• force: ${r.force}\n• mode: ${r.mode}\n• intent: ${r.intent}\n• posture: ${r.posture}\n• register: ${r.register}\n• certainty: ${r.certainty}`}
function renderCantusLab(){
 const f=foundation(),r=f.resonance||{};const options=(arr)=>arr.map(x=>`<option>${esc(x)}</option>`).join('');
 view.innerHTML=sectionTitle('Ademic Cantus + Resonance','Cantus carries structured meaning. Resonance carries tone and force. Ademic runes compress the result visually. Every symbol must remain reversible into plain language.')+
 `<div class="split cantus-workbench">
 <div class="card"><div class="tag">MEANING LAYER</div><form id="cantusForm" class="form"><label>Plain-language phrase<textarea id="cantusPhrase" required placeholder="Example: Protect this family while preserving their freedom."></textarea></label><div class="two-col"><label>Subject<input id="cSubject" placeholder="who / what"></label><label>Action<input id="cAction" placeholder="does what"></label><label>Relation / object<input id="cRelation" placeholder="to whom / what"></label><label>Context<input id="cContext" placeholder="where / why / situation"></label><label>Conditions<input id="cConditions" placeholder="if / when / limits"></label><label>Consent / boundary<input id="cConsent" placeholder="freedom, permission, no domination..."></label></div><div class="tag">RESONANCE LAYER</div><div class="two-col"><label>Tone<select id="cTone">${options(r.tone||[])}</select></label><label>Force<select id="cForce">${options(r.force||[])}</select></label><label>Mode<select id="cMode">${options(r.mode||[])}</select></label><label>Intent<select id="cIntent">${options(r.intent||[])}</select></label><label>Posture<select id="cPosture">${options(r.posture||[])}</select></label><label>Register<select id="cRegister">${options(r.register||[])}</select></label><label>Certainty<select id="cCertainty">${options(r.certainty||[])}</select></label></div><div class="actions"><button class="primary">Generate Ademic rune</button><button type="button" id="saveCantus" disabled>Save record</button></div></form></div>
 <div class="card rune-output"><div class="tag">ADemic RUNE · CONSTRUCTED NOT HISTORICAL</div><div id="cantusRune" class="rune-canvas"><span class="muted">Enter meaning and resonance to generate a reversible symbol.</span></div><pre id="cantusExpansion" class="cantus-expansion"></pre><div class="notice small">Compression is not secret knowledge. If a symbol cannot be expanded back into its declared meaning, Faithbook treats it as ambiguous.</div></div></div>
 <div class="card"><h2>Architecture</h2><div class="creation-path"><span>Source expression</span><b>→</b><span>Plain meaning</span><b>→</b><span>Ademic Cantus</span><b>→</b><span>Resonance</span><b>→</b><span>Runic compression</span><b>→</b><span>Plain-language expansion</span></div><div class="actions"><button data-route-card="runes">Rune Craft</button><button data-route-card="meaningcourse">Human Art of Meaning</button></div></div>`;
 let last=null;$('#cantusForm').onsubmit=e=>{e.preventDefault();last=cantusPayload();$('#cantusRune').innerHTML=ademicRuneSvg(last);$('#cantusExpansion').textContent=cantusExpansion(last);$('#saveCantus').disabled=false};$('#saveCantus').onclick=()=>{if(!last)return;const rr=saveGeneric('ademic_cantus',last.phrase||'Ademic Cantus expression',cantusExpansion(last),last);if(rr.ok)$('#saveCantus').disabled=true};wireRouteCards();
}

